/**
 * PR report bot — posts/updates a sticky PR comment with:
 *
 *   1. the runtime-size table delta vs the base branch
 *      (read from each tree's committed
 *      packages/pandwind/tests/snapshots/runtime-size.json.snap — no
 *      bundling needed, the exact-snapshot layer of the size gate is the
 *      source of truth), and
 *   2. the cx() fold-coverage percentage over a compact corpus that mirrors
 *      tests/vite-cx-coverage.test.ts patterns, measured through the REAL
 *      folding pass (`inlineCxCalls`) of both trees.
 *
 * Fail-open contract: nothing in this script may fail the workflow. Every
 * stage catches its own errors, degrades the affected section to "unavailable",
 * and always exits 0. Set DRY_RUN=1 to print the markdown instead of posting.
 *
 * Invocation (from repo root, see pr-report.yml):
 *   nub .github/scripts/pr-report.mjs
 * Environment:
 *   GH_TOKEN / PR_NUMBER / REPO  — GitHub posting (optional)
 *   BASE_DIR                     — path to the checked-out base branch tree
 *   BASE_REF_NAME                — human label for the base column
 *   DRY_RUN=1                    — print instead of post
 */
import { existsSync, mkdirSync, readFileSync, symlinkSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath, pathToFileURL } from "node:url";

const MARKER = "<!-- pandwind-pr-report -->";
const scriptDir = dirname(fileURLToPath(import.meta.url));
/** Script lives at <repo>/.github/scripts → repo root is two levels up. */
const repoRoot = resolve(scriptDir, "..", "..");
const baseDirEnv = process.env.BASE_DIR ? resolve(repoRoot, process.env.BASE_DIR) : undefined;
const baseLabel = process.env.BASE_REF_NAME || "base";

const warn = (msg) => console.warn(`[pr-report] warning: ${msg}`);
const rel = (dir, ...parts) => resolve(repoRoot, dir, ...parts);

async function main() {
	const sections = [];

	// ---- Section 1: runtime-size delta ---------------------------------
	try {
		sections.push(sizeSection());
	} catch (error) {
		warn(`size section failed: ${error?.message ?? error}`);
		sections.push("### Runtime size\n\n_unavailable (measurement error)_\n");
	}

	// ---- Section 2: fold coverage --------------------------------------
	try {
		sections.push(await coverageSection());
	} catch (error) {
		warn(`coverage section failed: ${error?.message ?? error}`);
		sections.push("### cx() fold coverage\n\n_unavailable (measurement error)_\n");
	}

	const body = `${MARKER}\n## pandwind report\n\n${sections.join("\n")}\n\n<sub>Generated by the PR report workflow · measurements are informational, the enforcing gate is CI.</sub>\n`;

	if (process.env.DRY_RUN === "1" || !process.env.PR_NUMBER || !process.env.GH_TOKEN) {
		console.log("--- comment body (not posted) ---");
		console.log(body);
		return;
	}
	await postOrUpdate(body);
	console.log("[pr-report] comment posted/updated.");
}

// ---------------------------------------------------------------- sizes --

function readSizes(dir) {
	const file = rel(dir, "packages", "pandwind", "tests", "snapshots", "runtime-size.json.snap");
	if (!existsSync(file)) throw new Error(`snapshot not found: ${file}`);
	return JSON.parse(readFileSync(file, "utf8"));
}

function fmtKb(bytes) {
	return `${(bytes / 1024).toFixed(2)} KB`;
}

function sizeSection() {
	const head = readSizes(repoRoot);
	const hasBase = Boolean(baseDirEnv && existsSync(rel(baseDirEnv, "package.json")));
	const base = hasBase ? readSizes(baseDirEnv) : undefined;

	const keys = [
		["css", "css()"],
		["tw", "tw()"],
		["cx", "cx()"],
		["all (css+tw+cx)", "all three"],
		["stylesheet generator (build-time only)", "generator (build-time)"],
	];

	let table = "| entry | head min | head gz |";
	let sep = "| --- | ---: | ---: |";
	if (base) {
		table += " base min | base gz | Δ min | Δ gz |";
		sep += " ---: | ---: | ---: | ---: |";
	}
	table += "\n" + sep;

	for (const [key, label] of keys) {
		if (!head[key]) continue;
		let row = `| ${label} | ${fmtKb(head[key].min)} | ${fmtKb(head[key].gz)} |`;
		if (base?.[key]) {
			const dMin = head[key].min - base[key].min;
			const dGz = head[key].gz - base[key].gz;
			const pctMin = base[key].min ? ((dMin / base[key].min) * 100).toFixed(1) : "0";
			row += ` ${fmtKb(base[key].min)} | ${fmtKb(base[key].gz)} | ${sign(dMin)} (${pctMin}%) | ${sign(dGz)} |`;
		}
		table += "\n" + row;
	}

	const note = hasBase ? "" : "\n\n_No base tree available — head values only._";
	return `### Runtime size (minified / gzip)\n\n${table}${note}`;
}

function sign(n) {
	if (n === 0) return "±0 B";
	return `${n > 0 ? "+" : ""}${n} B`;
}

// ------------------------------------------------------------ coverage --

const COVERAGE_CORPUS = [
	{ name: "static pair", source: `export const a = cx("px-2", "py-4");` },
	{
		name: "conflict chain",
		source: `export const b = cx("p-6", "px-4");`,
	},
	{
		name: "nested arrays",
		source: `export const c = cx(["flex", ["gap-4"]]);`,
	},
	{
		name: "module consts",
		source: `const PAD = "px-4 py-3";\nconst ROUND = "rounded-xl";\nexport const f = cx(PAD, ROUND, "shadow-sm");`,
	},
	{
		name: "template literal",
		source: "export const g = cx(`grid gap-2`);",
	},
	{
		name: "const interpolation",
		source: `const SHADE = "500";\nexport const h = cx(\`bg-red-\${SHADE} hover:bg-red-600\`);`,
	},
	{
		name: "static ternary (partial)",
		source: `export const i = cx(isActive ? "bg-blue-600 text-white" : "bg-gray-100 text-gray-900", "px-4 py-2 rounded-md");`,
	},
	{
		name: "logical guard (partial)",
		source: `export const j = cx(disabled && "opacity-50", "bg-emerald-500 text-white p-3");`,
	},
	{
		name: "cross-module const",
		imports: { PAD: "px-4 py-3" },
		source: `import { PAD } from "./styles/constants";\nexport const k = cx(PAD, "rounded-xl");`,
	},
	{
		name: "cross-module + partial mix",
		imports: { SHELL: "min-h-screen flex flex-col" },
		source: `import { SHELL } from "./styles/constants";\nexport const l = cx(SHELL, dark ? "bg-gray-900 text-white" : "bg-white text-gray-900");`,
	},
	{
		name: "dynamic key access stays runtime",
		source: `const tones = { primary: "bg-blue-500", danger: "bg-red-500" };\nexport const m = cx(tones[tone], "p-2");`,
	},
	{
		name: "rest params stay runtime",
		source: `export const n = (...parts: string[]) => cx(...parts, "flex");`,
	},
];

/**
 * The base checkout has no node_modules of its own. Its source modules need
 * bare-specifier resolution (oxc-parser & co.), so link the whole HEAD
 * packages/pandwind/node_modules directory in one piece — a single symlink
 * keeps pnpm's internal relative links resolving against the real install.
 */
function symlinkBaseNodeModules() {
	try {
		const srcNm = rel(repoRoot, "packages", "pandwind", "node_modules");
		if (!existsSync(srcNm)) return;
		const dstNm = rel(baseDirEnv, "packages", "pandwind", "node_modules");
		mkdirSync(dirname(dstNm), { recursive: true });
		if (!existsSync(dstNm)) symlinkSync(srcNm, dstNm, "dir");
	} catch (error) {
		warn(
			`base node_modules symlinking failed (${error?.message ?? error}) — base coverage column may be unavailable`,
		);
		throw error;
	}
}

async function loadTreeModules(dir) {
	const cxModule = await import(
		pathToFileURL(rel(dir, "packages", "pandwind", "src", "vite", "cx-inline.ts")).href
	);
	const inlineModule = await import(
		pathToFileURL(rel(dir, "packages", "pandwind", "src", "vite", "inline.ts")).href
	);
	const twSourcePath = rel(dir, "apps", "example", "src", "tw.ts");
	const config = inlineModule.extractTwConfig(readFileSync(twSourcePath, "utf8"));
	if (!config) throw new Error(`extractTwConfig returned nothing for ${dir}`);
	return { inlineCxCalls: cxModule.inlineCxCalls, config };
}

async function coverageSection() {
	const trees = [{ label: "head", dir: repoRoot }];
	if (baseDirEnv && existsSync(rel(baseDirEnv, "package.json"))) {
		symlinkBaseNodeModules();
		trees.push({ label: baseLabel, dir: baseDirEnv });
	}

	const results = [];
	for (const tree of trees) {
		// Sequential by design: each measurement loads a separate module graph
		// (two full compiler instances) — interleaving them doubles peak memory.
		try {
			results.push({ label: tree.label, ...(await measureTree(tree.dir)) });
		} catch (error) {
			warn(`coverage for ${tree.label} unavailable: ${error?.message ?? error}`);
			results.push({ label: tree.label, unavailable: true });
		}
	}

	const headResult = results[0];
	const baseResult = results.length > 1 ? results[1] : undefined;

	if (headResult.unavailable) {
		return "### cx() fold coverage\n\n_unavailable for head tree (measurement error)_\n";
	}

	let table =
		"| metric | head |" +
		(baseResult && !baseResult.unavailable ? ` ${baseLabel} | Δ |` : "") +
		"\n| --- | ---: |" +
		(baseResult && !baseResult.unavailable ? " ---: | ---: |" : "");
	const row = (label, key, ppUnit = false) => {
		let r = `\n| ${label} | **${headResult[key]}${ppUnit ? "%" : `/${headResult.total}`}** |`;
		if (baseResult && !baseResult.unavailable) {
			r += ` ${baseResult[key]}${ppUnit ? "%" : `/${baseResult.total}`} | ${deltaInt(headResult[key], baseResult[key])}${ppUnit ? " pp" : ""} |`;
		}
		return r;
	};
	table += row("fully eliminated", "full");
	table += row("partially folded", "partial");
	table += row("left at runtime", "runtime");
	table += row("**fold coverage**", "pct", true);

	const note =
		baseResult && !baseResult.unavailable
			? ""
			: "\n\n_Base tree unavailable or too old to measure — head values only._";
	return `### cx() fold coverage (build-time elimination)\n\n${table}${note}`;
}

/** Measures fold coverage through the current options-object folding API. */
async function measureTree(dir) {
	const { inlineCxCalls, config } = await loadTreeModules(dir);

	const runOne = (entry) => {
		const importedConstants = entry.imports
			? new Map(
					Object.entries(entry.imports).map(([name, value]) => [name, { value, declStart: 0 }]),
				)
			: undefined;
		return inlineCxCalls(entry.source, "app.ts", config, new Set(["cx"]), {
			constants: true,
			partialFold: true,
			...(importedConstants ? { importedConstants } : {}),
		});
	};

	let full = 0;
	let partial = 0;
	let runtimeCount = 0;
	for (const entry of COVERAGE_CORPUS) {
		const { code, inlined } = runOne(entry);
		if (inlined === 0) runtimeCount++;
		else if (code.includes(" ? ")) partial++;
		else full++;
	}
	const total = COVERAGE_CORPUS.length;
	return {
		full,
		partial,
		runtime: runtimeCount,
		total,
		pct: Math.round(((full + partial) / total) * 100),
	};
}

function deltaInt(head, base) {
	const d = head - base;
	return `${d > 0 ? "+" : ""}${d}`;
}

// ------------------------------------------------------------- posting --

async function postOrUpdate(body) {
	const { PR_NUMBER, REPO, GH_TOKEN } = process.env;
	const listed = runGh(
		[
			"api",
			`repos/${REPO}/issues/${PR_NUMBER}/comments`,
			"--jq",
			'.[] | select(.body | startswith("<!-- pandwind-pr-report -->")) | .id',
		],
		GH_TOKEN,
	);
	const existingId = listed
		.split("\n")
		.map((s) => s.trim())
		.find(Boolean);

	if (existingId) {
		runGh(
			[
				"api",
				"--method",
				"PATCH",
				"-f",
				`body=${body}`,
				`repos/${REPO}/issues/${PR_NUMBER}/comments/${existingId}`,
			],
			GH_TOKEN,
		);
	} else {
		runGh(
			[
				"api",
				"--method",
				"POST",
				"-f",
				`body=${body}`,
				`repos/${REPO}/issues/${PR_NUMBER}/comments`,
			],
			GH_TOKEN,
		);
	}
}

/**
 * Runs `gh api`. Returns stdout. Any failure throws — callers decide whether
 * that is fatal (nothing here treats it as fatal; the fail-open wrapper does).
 */
function runGh(args, token) {
	return execFileSync("gh", args, {
		env: { ...process.env, GH_TOKEN: token },
		encoding: "utf8",
		stdio: ["ignore", "pipe", "pipe"],
	});
}

// ------------------------------------------------------------- fail-open —

main()
	.catch((error) => {
		warn(`report skipped entirely: ${error?.message ?? error}`);
	})
	.finally(() => {
		process.exit(0);
	});
